function eb.weatherStrength(go)
local ho=eb.fx(go)
local io=ho.dmg/ho.cd/ho.hp/ho.speed*(1+(ho.range-1)/2)
for jo,ko in pairs(ho.kinds)do
io=io*(1+Q.rogueShare(jo)*ko)
end
if ho.ice>0 then
local mo=Q.rogueShare(CGc[1700])
io=io*(mo+(1-mo)/(1-ho.ice+ho.ice/W.modFactor(CGc[1751])))
end
if ho.fly>0 then
io=io*(1-ho.fly*0.5)
end
if ho.noCC then
io=io*0.95
end
if ho.shroud then
io=io*0.9
end
return io
end
