end
local ZC=H.Units[XC]
local _C=ZC.evolve and ZC.evolve.evolve_unit or XC
local aD={id=XC,to=_C,coins=H.cur(CGc[2052]),itemCost=0,needCoins=0}
for bD,cD in pairs(ZC.evolve and ZC.evolve.normal and ZC.evolve.normal.item_requirement or{})do
local dD=H.SaleEvent[cD.item_id]
if dD and type(dD.resource_cost)==CGc[1520]and dD.resource_cost.id==CGc[2052]then
aD.item,aD.itemCost=cD.item_id,tonumber(dD.resource_cost.amount)or 0
end
end
aD.haveItem=aD.item~=nil and ab.have(aD.item)>0
local eD,fD=P.hatched[XC]or false,false
for gD,hD in pairs(YC.collection.owned_units)do
if hD.unit_id==XC then
eD=true
end
if hD.unit_id==_C then
fD=true
end
end
if fD then
aD.step=CGc[2053]
elseif not eD then
aD.step,aD.needCoins=CGc[2054],1
elseif aD.item and not aD.haveItem then
aD.step,aD.needCoins=CGc[2022],math.max(0,aD.itemCost-aD.coins)
else
aD.step=CGc[2055]
end
return aD
end
