local nD=mD and tonumber(mD.opens_since_mythic)
return kD..string.format(CGc[2060]..CGc[2061]..CGc[2062],N.name(iD.id),M.fmt(iD.coins),math.max(0,math.floor((iD.coins-lD)/1500)),M.fmt(lD),N.name(iD.id),nD and string.format(CGc[2063],nD)or CGc[449],math.max(I.aprilValue,I.goalCoinValue),I.summonApril and CGc[2064]or CGc[2065])
elseif iD.step==CGc[2022]then
return kD..string.format(CGc[2066],N.name(iD.id),M.fmt(iD.itemCost),M.fmt(iD.coins))
elseif iD.step==CGc[2055]then
