function db.relicWorth(hL,iL)
local jL=iL._unique_item_data and iL._unique_item_data._unique_relic_data
if not jL then
return 0
end
local kL=H.Items[iL.item_id]or{}
local lL,mL=N.types(hL.unit_id)
if kL.main_damage_type and kL.main_damage_type~=CGc[2145]and kL.main_damage_type~=mL then
return 0
end
local nL,oL=0,0
for pL,qL in pairs(jL._core_damage_type_buffs or{})do
if lL[qL.damage_type]then
nL=nL+(tonumber(qL.mul)or 0)+(tonumber(qL.add_upg)or 0)*0.01+(tonumber(qL.pen)or 0)*0.001
oL=oL+(tonumber(qL.crit)or 0)
end
end
nL=nL+oL*0.5
local rL=N.rows(hL.unit_id)
local sL=rL and rL[rL.max]
local tL=(sL and tonumber(sL.cd)or 0)*N.mult(hL,CGc[1656])
for uL,vL in pairs(jL._unique_relic_effects or{})do
local wL=type(vL.params)==CGc[1520]and vL.params or{}
if vL.id==CGc[2146]then
local xL=math.min(1,(tonumber(wL.extra_damage)or 0)*tL/math.max(1,tonumber(wL.time_interval)or 40))
local yL=N.DRONES and N.DRONES[hL.unit_id]
if yL and yL.late and tL>0 then
local zL=1/tL
xL=xL*zL/(zL+(tonumber(yL.max)or 0)*(tonumber(yL.late.dmg)or 0)*(tonumber(yL.hits)or 1)/math.max(0.1,tonumber(yL.late.cd)or 4))
end
nL=nL+xL
elseif vL.id==CGc[2147]then
nL=nL+(tonumber(wL.dmg_buff)or 0)*0.25
elseif vL.id==CGc[2148]then
nL=nL+(tonumber(wL.dmg_buff)or 0)*oL
elseif vL.id==CGc[2149]then
if lL.magic then
nL=0
else
nL=nL+(tonumber(wL.dmg_buff)or 0)*0.3
end
elseif vL.id==CGc[2150]then
if lL.water_damage then
nL=nL+0.05
end
end
end
return nL
end
function db.relicPlan()
