dM(eM+1,fM+iM.w+(iM.it.uuid==gM.e.u._equipped_relic and 0.01 or 0))
aM[gM.e.uuid]=nil
bM[iM.it.uuid]=nil
if jM then
cM[iM.it.item_id]=nil
