end
end
end
dM(1,0)
local kM,lM=0,{}
for mM,nM in ipairs(FL)do
local oM=nM.e.u._equipped_relic and AL.inventory:get_item_by_uuid(nM.e.u._equipped_relic)
local pM=oM and db.relicWorth(nM.e.u,oM)*nM.share*100 or 0
