Ypb.margin=Zpb.won and CGc[2758]or CGc[2759]
else
local _pb=W.run(Vpb,Wpb,{hpMul=0.75})
Ypb.p=_pb.won and 0.25 or 0.05
Ypb.margin=_pb.won and string.format(CGc[2760],Xpb.wave)or string.format(CGc[2761],Xpb.wave,Vpb.total)
if not _pb.won then
