local uqb=tonumber(lqb.alive[tostring(tqb)])
local vqb=pqb.aliveAt[tqb]
if uqb and vqb and uqb>0 then
qqb=qqb+uqb
rqb=rqb+vqb
sqb=sqb+1
end
end
if sqb<2 or rqb<=0 then
return nil
end
local wqb=qqb/rqb
return{ratio=wqb,ok=wqb>=0.75 and wqb<=1.33,waves=sqb}
end
W.GROWN_LEVEL,W.GROWN_MIN=50,6
function W.grownKinds()
local xqb=H.session()
local yqb,zqb={},0
for Aqb,Bqb in pairs(xqb.profile_data.collection.owned_units)do
local Cqb=Bqb.unit_id
if not yqb[Cqb]and H.Units[Cqb]and not N.isFarm(Cqb)and N.rows(Cqb)and not N.hidden(Cqb)then
local Dqb,Eqb=pcall(H.USC.calculate_level,Cqb,tonumber(Bqb.xp)or 0)
if Dqb and(tonumber(Eqb)or 0)>=W.GROWN_LEVEL then
yqb[Cqb]=true
zqb=zqb+1
end
end
end
return zqb
end
function W.pool(Fqb,Gqb)
local Hqb=H.session()
local Iqb,Jqb={},{}
local Kqb=W.grownKinds()>=W.GROWN_MIN
for Lqb,Mqb in pairs(Hqb.profile_data.collection.owned_units)do
local Nqb=Hqb.collection:get_unit_by_uuid(Mqb.uuid)or Mqb
local Oqb,Pqb=pcall(H.USC.calculate_level,Nqb.unit_id,tonumber(Nqb.xp)or 0)
local Qqb=N.isFarm(Nqb.unit_id)or not Kqb or(Oqb and(tonumber(Pqb)or 0)>=W.GROWN_LEVEL)
if H.Units[Nqb.unit_id]and N.rows(Nqb.unit_id)and not N.hidden(Nqb.unit_id)and Qqb then
local Rqb=N.isFarm(Nqb.unit_id)
local Sqb,Tqb=pcall(Rqb and function()
return N.farm(Nqb,N.rows(Nqb.unit_id).max)
end or N.score,Nqb,Fqb)
Tqb=(Sqb and Tqb or 0)*(Rqb and 1 or N.skinMul(Nqb,Gqb and Gqb.skinSet))
local Uqb=Rqb and Jqb or Iqb
if not Uqb[Nqb.unit_id]or Tqb>Uqb[Nqb.unit_id].sc then
Uqb[Nqb.unit_id]={u=Nqb,sc=Tqb}
end
end
end
local Vqb,Wqb={},{}
for Xqb,Yqb in pairs(Iqb)do
table.insert(Vqb,Yqb)
end
for Zqb,_qb in pairs(Jqb)do
table.insert(Wqb,_qb)
end
table.sort(Vqb,function(arb,brb)
return arb.sc>brb.sc
end)
table.sort(Wqb,function(crb,drb)
return crb.sc>drb.sc
end)
local erb={}
for frb=1,math.min(10,#Vqb)do
table.insert(erb,Vqb[frb].u)
end
local grb,hrb={},{}
for irb=11,#Vqb do
local jrb=N.rows(Vqb[irb].u.unit_id)
for krb=0,jrb.max do
if jrb[krb]and jrb[krb].atk and N.attackInfo(jrb[krb].atk,jrb[krb].range).dot>0 then
table.insert(krb==0 and grb or hrb,Vqb[irb].u)
break
end
end
end
for lrb=1,math.min(4,#grb)do
table.insert(erb,grb[lrb])
end
for mrb=1,math.min(2,#hrb)do
table.insert(erb,hrb[mrb])
end
for nrb=1,math.min(3,#Wqb)do
table.insert(erb,Wqb[nrb].u)
end
local orb={}
for prb=11,#Vqb do
local qrb=N.rows(Vqb[prb].u.unit_id)[0]
local rrb=qrb and qrb.atk and N.attackInfo(qrb.atk,qrb.range)
if rrb and(rrb.slowTime>0 or rrb.stun>0)then
table.insert(orb,Vqb[prb].u)
end
end
for srb=1,math.min(3,#orb)do
table.insert(erb,orb[srb])
end
for trb=11,#Vqb do
local urb=Vqb[trb].u.unit_id
if N.allyBuff(urb)or N.BLESS.by[urb]or N.GALE[urb]then
table.insert(erb,Vqb[trb].u)
end
end
if Gqb and((Gqb.flyChance or 0)>0 or Gqb.mapFly or(Gqb.shield or 0)>0)then
local vrb,wrb={},{}
for xrb=11,#Vqb do
local yrb=Vqb[xrb].u
local zrb=N.rows(yrb.unit_id)[0]
if N.airFrom(yrb.unit_id)==0 then
table.insert(vrb,yrb)
end
local Arb,Brb=tonumber(zrb and zrb.cd)or 0,tonumber((H.Units[yrb.unit_id]or{}).cost)or 0
if Arb>0 and Brb>0 and N.range(yrb,0)>=15 then
local Crb=N.attackInfo(zrb.atk,zrb.range)
table.insert(wrb,{u=yrb,v=Crb.n*Crb.hits/Arb/Brb*math.min(6,N.cap(yrb))})
end
end
table.sort(wrb,function(Drb,Erb)
return Drb.v>Erb.v
end)
for Frb=1,math.min(4,#vrb)do
table.insert(erb,vrb[Frb])
end
for Grb=1,math.min(6,#wrb)do
table.insert(erb,wrb[Grb].u)
end
end
local Hrb,Irb={},{}
for Jrb,Krb in ipairs(erb)do
if not Hrb[Krb]then
Hrb[Krb]=true
table.insert(Irb,Krb)
end
end
Irb.rest={}
for Lrb,Mrb in ipairs(Vqb)do
if not Hrb[Mrb.u]then
table.insert(Irb.rest,Mrb.u)
end
end
return Irb
end
function W.objective(Nrb)
return(Nrb.won and 1000 or 0)+Nrb.wave*10-(Nrb.won and Nrb.t/60 or((Nrb.left or 1)*9-math.min(9,Nrb.t/60)))
end
W.LADDER={1,1.3,1.7,2.2,3,4,6,8,12,16,24}
function W.cliff(Orb,Prb,Qrb)
local Rrb
for Srb,Trb in ipairs(W.LADDER)do
Rrb=W.run(Orb,Prb,{hpMul=Trb,layout=Qrb})
if not Rrb.won then
return Trb,Rrb
end
end
return W.LADDER[#W.LADDER],Rrb
end
function W.exam(Urb,Vrb)
local Wrb,Xrb,Yrb=W.teamFrom(Vrb,Urb.map),0,0
for Zrb,_rb in ipairs(W.LADDER)do
local asb,bsb=0,0
for csb,dsb in ipairs({0.92,1,1.08})do
local esb=W.run(Urb,Wrb,{hpMul=_rb*dsb})
if esb.won then
asb=asb+1
end
bsb=bsb+esb.wave
end
Xrb,Yrb=Xrb+asb,bsb/3
task.wait()
if asb==0 then
break
end
end
return Xrb,Yrb
end
W.ZONE_CLOSE,W.ZONE_GAIN=1.3,20
function W.zoneKey(fsb)
return tostring(fsb.key)..CGc[1631]..tostring(fsb.map)
end
function W.zoneChoice(gsb,hsb,isb,jsb)
if I.killZone==false or gsb.zone or(gsb.infinite and W.unbound(gsb.ld))then
return false
end
local ksb=J.zoneRec[W.zoneKey(gsb)]
local lsb=ksb and(ksb.style==CGc[2745]or(ksb.style==nil and ksb.zone==true))
if ksb and ksb.won then
return lsb==true,lsb and CGc[2765]or nil
end
if ksb and lsb then
return false,CGc[2766]
end
local msb=J.modes[gsb.key]
local nsb=msb and tonumber(msb.streak)or 0
if not ksb and msb and(tonumber(msb.wins)or 0)>0 and nsb==0 and gsb.key~=CGc[1835]and gsb.key~=CGc[1831]then
return false
end
local osb=ksb~=nil or nsb>0
local psb=jsb and isb<=1 or(not jsb and isb<=W.ZONE_CLOSE)
if not(osb or psb)then
return false
end
local qsb=table.clone(gsb)
qsb.zone=true
local function rsb(ssb)
local tsb=0
for usb,vsb in ipairs({0.92,1,1.08})do
tsb=tsb+W.objective(W.run(ssb,hsb,{hpMul=isb*vsb}))
end
return tsb/3
end
local wsb=rsb(qsb)-rsb(gsb)
if osb and wsb> -W.ZONE_GAIN then
return true,CGc[2767],wsb
end
if psb and wsb>W.ZONE_GAIN then
return true,string.format(CGc[2768],isb),wsb
end
return false,nil,wsb
end
function W.strength(xsb,ysb)
local zsb,Asb,Bsb,Csb,Dsb=W.teamFrom(ysb,xsb.map),0,0,0,0
for Esb,Fsb in ipairs(W.LADDER)do
local Gsb,Hsb=0,0
for Isb,Jsb in ipairs({0.92,1,1.08})do
local Ksb=W.run(xsb,zsb,{hpMul=Fsb*Jsb})
if Ksb.won then
Gsb=Gsb+1
end
Hsb=Hsb+Ksb.wave
end
Asb,Dsb=Asb+Gsb,Hsb/3
if Fsb==1 then
Bsb,Csb=Gsb,Hsb/3
end
task.wait()
if Gsb==0 then
break
end
end
return Asb,Bsb,Csb,Dsb
end
function W.bestTeam(Lsb,Msb,Nsb,Osb)
local Psb=M.now()
Osb=Osb or 25
local Qsb=table.clone(Msb)
local Rsb,Ssb=W.cliff(Lsb,W.teamFrom(Qsb,Lsb.map))
local function Tsb(Usb)
local Vsb=0
for Wsb,Xsb in ipairs(Usb)do
if N.isFarm(Xsb.unit_id)then
Vsb=Vsb+1
end
end
return Vsb
end
local Ysb=Tsb(Nsb)>0
local function Zsb(_sb)
local atb=0
for btb,ctb in ipairs(_sb)do
if not N.isFarm(ctb.unit_id)and not N.allyBuff(ctb.unit_id)then
atb=atb+N.cap(ctb)
end
end
return atb
end
local dtb
while#Qsb<6 do
local etb,ftb
local gtb=Ysb and Tsb(Qsb)==0
for htb,itb in ipairs(Nsb)do
local jtb=false
for ktb,ltb in ipairs(Qsb)do
if ltb.unit_id==itb.unit_id then
jtb=true
end
end
if not jtb and(not gtb or N.isFarm(itb.unit_id))then
local mtb=table.clone(Qsb)
table.insert(mtb,itb)
local ntb=W.run(Lsb,W.teamFrom(mtb,Lsb.map),{hpMul=Rsb})
local otb=W.objective(ntb)
if not ftb or otb>ftb then
etb,ftb,dtb=itb,otb,ntb
end
end
end
if not etb then
break
end
table.insert(Qsb,etb)
end
if Ysb and Tsb(Qsb)==0 then
local ptb,qtb
for rtb=1,#Qsb do
for stb,ttb in ipairs(Nsb)do
if N.isFarm(ttb.unit_id)then
local utb=table.clone(Qsb)
utb[rtb]=ttb
local vtb=W.run(Lsb,W.teamFrom(utb,Lsb.map),{hpMul=Rsb})
local wtb=W.objective(vtb)
if not qtb or wtb>qtb then
ptb,qtb,dtb=utb,wtb,vtb
end
end
end
end
if ptb then
Qsb=ptb
end
end
local function xtb(ytb,ztb)
local Atb=W.teamFrom(ytb,Lsb.map)
return(W.objective(ztb)+W.objective(W.run(Lsb,Atb,{hpMul=Rsb*0.92}))+W.objective(W.run(Lsb,Atb,{hpMul=Rsb*1.08})))/3
end
local Btb,Ctb=dtb or Ssb,xtb(Qsb,dtb or Ssb)
if type(Nsb.rest)==CGc[1520]and#Nsb.rest>0 then
local Dtb,Etb
for Ftb,Gtb in ipairs(Qsb)do
if not N.isFarm(Gtb.unit_id)and not N.allyBuff(Gtb.unit_id)then
local Htb,Itb=pcall(N.score,Gtb,Lsb.mod)
Itb=(Htb and Itb or 0)*N.skinMul(Gtb,Lsb.skinSet)
if not Etb or Itb<Etb then
Dtb,Etb=Ftb,Itb
end
end
end
if Dtb then
local Jtb,Ktb={},M.now()
for Ltb,Mtb in ipairs(Nsb.rest)do
if M.now()-Ktb>5 then
break
end
local Ntb=false
for Otb,Ptb in ipairs(Qsb)do
if Ptb.unit_id==Mtb.unit_id then
Ntb=true
end
end
if not Ntb then
local Qtb=table.clone(Qsb)
Qtb[Dtb]=Mtb
table.insert(Jtb,{u=Mtb,o=W.objective(W.run(Lsb,W.teamFrom(Qtb,Lsb.map),{hpMul=Rsb}))})
end
end
table.sort(Jtb,function(Rtb,Stb)
return Rtb.o>Stb.o
end)
Nsb=table.clone(Nsb)
for Ttb=1,math.min(4,#Jtb)do
table.insert(Nsb,1,Jtb[Ttb].u)
end
Psb=Psb+(M.now()-Ktb)
end
end
for Utb=1,2 do
local Vtb=false
for Wtb=1,#Qsb do
for Xtb,Ytb in ipairs(Nsb)do
if M.now()-Psb>Osb then
return Qsb,Btb,Rsb,Ssb
end
local Ztb=false
for _tb,aub in ipairs(Qsb)do
if aub.unit_id==Ytb.unit_id then
Ztb=true
end
end
if not Ztb then
local bub=table.clone(Qsb)
bub[Wtb]=Ytb
if(not Ysb or Tsb(bub)>0)and Zsb(bub)>=math.min(8,Zsb(Qsb))then
local cub=W.run(Lsb,W.teamFrom(bub,Lsb.map),{hpMul=Rsb})
local dub=W.objective(cub)
if dub>Ctb+1 then
dub=xtb(bub,cub)
if dub>Ctb+1 then
Qsb,Ctb,Btb,Vtb=bub,dub,cub,true
end
end
end
end
end
end
if not Vtb then
break
end
end
return Qsb,Btb,Rsb,Ssb
end
function W.evolutions()
local eub=H.session()
local fub,gub={},{}
local hub=eub.inventory
local function iub(jub)
local kub=0
pcall(function()
kub=hub:get_number_of_owned_item(jub)
end)
return kub
end
for lub,mub in pairs(eub.profile_data.collection.owned_units)do
local nub=H.Units[mub.unit_id]
if nub and nub.evolve and nub.evolve.evolve_unit and not nub.evolve.hide_from_ui and not gub[mub.unit_id]and H.Units[nub.evolve.evolve_unit]then
gub[mub.unit_id]=true
local oub=mub.shiny and nub.evolve.shiny or nub.evolve.normal
if oub then
local pub={}
for qub,rub in pairs(oub.item_requirement or{})do
if iub(rub.item_id)<(rub.amount or 1)then
table.insert(pub,string.format(CGc[2115],(H.Items[rub.item_id]or{}).name or rub.item_id,iub(rub.item_id),rub.amount))
end
end
for tub,uub in pairs(oub.unit_requirement or{})do
local vub=0
for wub,xub in pairs(eub.profile_data.collection.owned_units)do
if xub.unit_id==uub.unit_id and(not uub.shiny or xub.shiny)then
vub=vub+1
end
end
if vub<(uub.amount or 1)then
table.insert(pub,string.format(CGc[2115],N.name(uub.unit_id),vub,uub.amount))
end
end
local yub=ab.killsShort(eub.collection:get_unit_by_uuid(mub.uuid)or mub,oub)
if yub then
table.insert(pub,string.format(CGc[2399],yub.what,M.fmt(yub.have),M.fmt(yub.need)))
end
if#pub<=1 then
local zub=eub.collection:get_unit_by_uuid(mub.uuid)or mub
table.insert(fub,{u=zub,from=mub.unit_id,to=nub.evolve.evolve_unit,missing=pub,evolved={unit_id=nub.evolve.evolve_unit,uuid=CGc[2107]..tostring(zub.uuid),xp=zub.xp,traits=zub.traits,trait_stats=zub.trait_stats,further_modifiers=zub.further_modifiers}})
end
end
end
end
return fub
end
