function W.typeWord(Fub)
return(tostring(Fub):gsub(CGc[2769],CGc[449]))
end
function W.against(Gub)
local Hub=W.typeWord
local Iub={}
if not Gub then
return Iub
end
local Jub,Kub=pcall(W.unbound,Gub.ld)
table.insert(Iub,(Gub.infinite and Jub and Kub)and CGc[2770]or string.format(CGc[2771],tonumber(Gub.total)or 0))
local Lub=Gub.mod or{}
local Mub,Nub,Oub={},{},{}
for Pub,Qub in pairs(Lub.weak or{})do
