end
end
end
if(Gub.flyChance or 0)>0 then
Zub.Flying=true
end
if Gub.armorAll then
Zub.Armor=true
end
if(Gub.shield or 0)>0 then
Zub.Shield=true
end
local evb={Flying=CGc[2778],Armor=CGc[2779],Ice=CGc[2780],Fire=CGc[1700],Soaring=CGc[2781],Burst=CGc[2782],Shield=CGc[2783]}
local fvb={}
for gvb in pairs(Zub)do
table.insert(fvb,evb[gvb]or tostring(gvb):lower())
end
table.sort(fvb)
if#fvb>0 then
table.insert(Iub,CGc[2784]..table.concat(fvb,CGc[1616]))
end
if(Gub.red or 0)>0 then
table.insert(Iub,string.format(CGc[2785],math.floor(Gub.red*100+0.5)))
end
