table.insert(ivb,string.format(CGc[2787],hvb.hp))
end
if math.abs((hvb.speed or 1)-1)>0.001 then
table.insert(ivb,string.format(CGc[2788],hvb.speed))
end
if(hvb.fly or 0)>0 then
table.insert(ivb,string.format(CGc[2789],math.floor(hvb.fly*100+0.5)))
end
if(hvb.ice or 0)>0 then
table.insert(ivb,string.format(CGc[2790],math.floor(hvb.ice*100+0.5)))
end
