if math.abs((hvb.dmg or 1)-1)>0.001 then
table.insert(jvb,string.format(CGc[2793],hvb.dmg))
end
if math.abs((hvb.cd or 1)-1)>0.001 then
table.insert(jvb,string.format(CGc[2794],hvb.cd))
end
