function Q.buildPath()
Q.samples={}
local XGb=H.PATH and H.PATH.PATH_CACHE and H.PATH.PATH_CACHE[workspace._BASES.pve]
if not XGb then
return
end
for YGb,ZGb in pairs(XGb)do
if not(H.PATH.HIDDEN_MOCK_LANES and H.PATH.HIDDEN_MOCK_LANES[YGb.Name])then
local _Gb={}
for aHb,bHb in ipairs(ZGb.points or{})do
table.insert(_Gb,bHb.part.Position)
end
local cHb=0
for dHb=2,#_Gb do
cHb=cHb+(_Gb[dHb]-_Gb[dHb-1]).Magnitude
end
local eHb=0
for fHb=2,#_Gb do
local gHb,hHb=_Gb[fHb-1],_Gb[fHb]
local iHb=(hHb-gHb).Magnitude
local jHb=math.max(1,math.floor(iHb/2))
for kHb=0,jHb-1 do
local lHb=gHb:Lerp(hHb,kHb/jHb)
table.insert(Q.samples,{pos=lHb,prog=(eHb+iHb*kHb/jHb)/math.max(1,cHb),lane=YGb.Name})
end
eHb=eHb+iHb
end
if _Gb[#_Gb]then
table.insert(Q.samples,{pos=_Gb[#_Gb],prog=1,lane=YGb.Name})
end
end
end
Q.laneCut,Q.laneWant,Q.laneFirst=nil,nil,nil
local mHb=tonumber(Q.ld and Q.ld._portal_lanes)
local nHb=W.laneList(Q.samples)
if mHb and mHb>=1 and nHb and#nHb>mHb then
Q.laneWant=mHb
