local uHb,vHb={},0
for wHb,xHb in ipairs(workspace._UNITS:GetChildren())do
local yHb=xHb:FindFirstChild(CGc[1579])
if yHb and yHb:FindFirstChild(CGc[3045])and yHb.player.Value==nil and yHb:FindFirstChild(CGc[3046])and xHb:FindFirstChild(CGc[3047])then
