if not mUb(kUb.id)or N.toggleOf(kUb.id)then
return nil
end
local nUb,oUb,pUb,qUb=1,0,0,{}
for rUb,sUb in ipairs(Q.mine or{})do
local tUb=sUb._stats
local uUb=tUb.id.Value
if tUb:FindFirstChild(CGc[1658])and not N.isFarm(uUb)and not N.allyBuff(uUb)then
local vUb,wUb=M.flat(sUb:GetPivot().Position),tUb.range.Value
if mUb(uUb)and not N.toggleOf(uUb)then
pUb=pUb+1
table.insert(qUb,{p=vUb,r=wUb})
else
for xUb,yUb in ipairs(Q.samples)do
if(M.flat(yUb.pos)-vUb).Magnitude<=wUb then
nUb,oUb=math.min(nUb,yUb.prog),math.max(oUb,yUb.prog)
end
end
end
end
end
if oUb<=nUb then
nUb,oUb=0.75,0.98
end
local zUb=(lUb or pUb)+1
local AUb=({nUb,oUb,(nUb+oUb)/2,nUb-(oUb-nUb)/2})[zUb]
if not AUb then
return nil
end
local BUb=N.range(kUb.u,0)*((Q.info and tonumber(Q.info.rangeScale))or 1)
local CUb={}
for DUb,EUb in ipairs(Q.cands)do
local FUb,GUb,HUb=M.flat(EUb),0,0
for IUb,JUb in ipairs(Q.samples)do
if(M.flat(JUb.pos)-FUb).Magnitude<=BUb then
HUb=HUb+1
if math.abs(JUb.prog-AUb)<=0.05 then
GUb=GUb+1
local KUb=M.flat(JUb.pos)
for LUb,MUb in ipairs(qUb)do
if(KUb-MUb.p).Magnitude<=MUb.r then
GUb=GUb-0.5
break
end
end
end
end
end
if GUb>0 then
table.insert(CUb,{pos=EUb,sc=GUb,cov=HUb})
end
if DUb%60==0 then
task.wait()
end
end
table.sort(CUb,function(NUb,OUb)
return NUb.sc>OUb.sc
end)
for PUb,QUb in ipairs(CUb)do
local RUb=Q.valid(QUb.pos,kUb.data)
if RUb then
j.log(1,CGc[3175],string.format(CGc[3176],N.name(kUb.id),Q.CONTROL_WORDS[zUb],math.floor(AUb*100+0.5)))
return RUb,QUb.cov,AUb
end
if PUb%20==0 then
task.wait()
end
end
return nil
end
function Q.holdSpot(SUb)
