Q.placeLog=Q.placeLog or{}
table.insert(Q.placeLog,{t=math.floor(M.now()-(Q.startT or M.now())),w=Q.wave(),id=gYb.id,x=math.floor(jYb.X),z=math.floor(jYb.Z),cover=math.floor((kYb or 0)+0.5),why=tostring(hYb):sub(1,90)})
