local x9b={}
for y9b,z9b in pairs(Q.ownDealt or{})do
if not N.isFarm(z9b.id)then
x9b[z9b.id]=(x9b[z9b.id]or 0)+(tonumber(z9b.v)or 0)
end
end
for A9b,B9b in pairs(Q.helperDealt or{})do
if B9b.owner and N.SUMMONER[B9b.owner]then
x9b[B9b.owner]=(x9b[B9b.owner]or 0)+(tonumber(B9b.v)or 0)
end
end
local C9b,D9b=0,0
for E9b,F9b in pairs(w9b)do
if F9b>0 then
C9b=C9b+(x9b[E9b]or 0)
D9b=D9b+F9b
end
end
if C9b<=0 or D9b<=0 then
return
end
