Q9b.n=(tonumber(Q9b.n)or 0)+1
N9b[O9b]=Q9b
end
N9b._at=os.time()
J.mapLearn[M9b]=N9b
if M.count(J.mapLearn)>80 then
local S9b,T9b
for U9b,V9b in pairs(J.mapLearn)do
if not T9b or(tonumber(V9b._at)or 0)<T9b then
S9b,T9b=U9b,tonumber(V9b._at)or 0
