function Q.shieldNow()
local Gbc=Q.wave()
if Q._shieldW~=Gbc then
Q._shieldW,Q._shieldS,Q._shieldH=Gbc,0,1
local Hbc,Ibc=pcall(W.wave,Q.info,math.max(1,Gbc),true)
if Q.info and Hbc and#Ibc>0 then
local Jbc,Kbc=0,0
for Lbc,Mbc in ipairs(Ibc)do
Jbc,Kbc=Jbc+(Mbc.sh or 0),Kbc+Mbc.hp
end
Q._shieldS,Q._shieldH=Jbc/ #Ibc,Kbc/ #Ibc
end
end
return Q._shieldS,Q._shieldH
