function Q.shieldOf(Nbc,Obc)
local Pbc,Qbc=Q.shieldNow()
if Pbc<=0 or not Obc then
return Nbc
end
local Rbc=N.attackInfo(Obc.atk,Obc.range)
return V.shieldDps(Nbc,tonumber(Obc.cd)or 2,Rbc.n,Pbc,Qbc,Q.info and Q.info.eff,Rbc.hits)
