function Q.shieldWork(Sbc,Tbc)
local Ubc,Vbc=Q.shieldNow()
if Ubc<=0 or not Tbc or not Q.info then
return 0
end
local Wbc,Xbc=0,0
for Ybc,Zbc in ipairs(Q.team or{})do
local _bc=N.rows(Zbc.id)
_bc=_bc and _bc[0]
if _bc and not N.isFarm(Zbc.id)then
Wbc=math.max(Wbc,N.dps(Zbc.u,0,Q.mod)*(tonumber(_bc.cd)or 2)/math.max(1,N.attackInfo(_bc.atk,_bc.range).n))
end
end
for acc,bcc in ipairs(Q.mine or{})do
local ccc=bcc._stats.id.Value
local dcc=N.rows(ccc)
local ecc=dcc and dcc[bcc._stats.upgrade and bcc._stats.upgrade.Value or 0]
if ecc and not N.isFarm(ccc)and not N.allyBuff(ccc)then
local fcc=N.attackInfo(ecc.atk,ecc.range)
Xbc=Xbc+fcc.n*fcc.hits/math.max(0.3,tonumber(ecc.cd)or 2)
end
end
local gcc,hcc=pcall(W.wave,Q.info,math.max(1,Q.wave()),true)
local icc=N.attackInfo(Tbc.atk,Tbc.range)
return V.shieldWork(icc.n,tonumber(Tbc.cd)or 2,Xbc,Ubc,gcc and#hcc or 1,Q.info.waveSec,Wbc*(Q.info.eff or 1),Vbc,icc.hits)
