function Q.teamShield()
if Q._shieldAt and M.now()-Q._shieldAt<2 then
return Q._shieldTeam
end
local jcc,kcc=0,0
for lcc,mcc in ipairs(Q.mine or{})do
local ncc=mcc._stats.id.Value
if not N.isFarm(ncc)and mcc._stats:FindFirstChild(CGc[1606])then
local occ=N.rows(ncc)
local pcc,qcc=pcall(Q.liveDps,mcc,ncc)
if pcc and occ then
